/**
 * Rich per-chromosome feature content for the Analysis pages.
 * Curated from the Chromosome_Features markdown documents.
 */

export interface FeatureEntry {
  term: string;
  detail: string;
}

export interface GeneEntry {
  symbol: string;
  band: string;
  detail: string;
}

export interface ChromosomeFeatureData {
  tagline: string;
  physicalProperties: FeatureEntry[];
  genomicArchitecture: FeatureEntry[];
  notableGenes: GeneEntry[];
  diseaseAssociations: FeatureEntry[];
  evolutionaryHistory: FeatureEntry[];
  biophysicalFeatures: FeatureEntry[];
  epigeneticLandscape: FeatureEntry[];
  deepCuts: FeatureEntry[];
}

